date_default_timezone_set('America/New_York');
$publicRoot=dirname(__DIR__);$installerDir=__DIR__;$raceDir=$publicRoot.'/race_results';
$targetPage=$publicRoot.'/admin_paid_payouts.php';$targetHelper=$publicRoot.'/admin_paid_payouts_helper.php';
$oldPage=$raceDir.'/admin_paid_payouts.php';$oldHelper=$raceDir.'/admin_paid_payouts_helper.php';
$backupDir=$publicRoot.'/_installer_backups/install_admin_paid_payouts_v002_'.date('Ymd_hisA');
$stateFile=$installerDir.'/.install_admin_paid_payouts_v002_state.json';
$PAGE_B64='';$HELPER_B64='';
$PAGE_SHA='4e972ea91c79fc82dcf1a87268d330e49da8e909f5967d193b4459cdb0f77cd1';$HELPER_SHA='ff03de00e87ad393286ce412cde775bdd30c363e006fb76ab0a9e100bffbfa12';

function ih($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function nowEt():string{return date('c');}
function addCheck(array &$a,string $label,bool $ok,bool $req,string $detail=''):void{$a[]=['label'=>$label,'status'=>$ok?'PASS':'FAIL','required'=>$req,'detail'=>$detail];}
function allPass(array $a):bool{foreach($a as $x)if(!empty($x['required'])&&($x['status']??'')!=='PASS')return false;return true;}
function phpLint(string $f):array{$o=shell_exec('php -l '.escapeshellarg($f).' 2>&1');$o=is_string($o)?trim($o):'';return [strpos($o,'No syntax errors detected')!==false,$o?:'No lint output'];}
function atomicWrite(string $f,string $c):bool{$d=dirname($f);$t=tempnam($d,'.mrl_tmp_');if($t===false)return false;$ok=file_put_contents($t,$c,LOCK_EX)!==false;if($ok)@chmod($t,0644);if($ok)$ok=@rename($t,$f);if(!$ok&&is_file($t))@unlink($t);return $ok;}
function colExists(PDO $dbo,string $table,string $col):bool{try{$s=$dbo->prepare("SHOW COLUMNS FROM `".$table."` LIKE :c");$s->execute([':c'=>$col]);return (bool)$s->fetch(PDO::FETCH_ASSOC);}catch(Throwable $e){return false;}}
function tableExists(PDO $dbo,string $table):bool{try{$s=$dbo->prepare("SHOW TABLES LIKE :t");$s->execute([':t'=>$table]);return (bool)$s->fetch(PDO::FETCH_NUM);}catch(Throwable $e){return false;}}
function ensureSchema(PDO $dbo):array{
 $notes=[];
 $dbo->exec("CREATE TABLE IF NOT EXISTS `mrl_financial_fee_history` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`raceYear` INT NOT NULL,`annual_fee` DECIMAL(10,2) NOT NULL DEFAULT 0.00,`effective_date` DATE NOT NULL,`reason` VARCHAR(255) NOT NULL DEFAULT '',`changed_by` INT NOT NULL DEFAULT 0,`created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),KEY `idx_fee_year_date` (`raceYear`,`effective_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $dbo->exec("CREATE TABLE IF NOT EXISTS `mrl_financial_team_year` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`raceYear` INT NOT NULL,`userID` INT NOT NULL,`teamName` VARCHAR(255) NOT NULL DEFAULT '',`userName` VARCHAR(255) NOT NULL DEFAULT '',`amount_paid` DECIMAL(10,2) NOT NULL DEFAULT 0.00,`paid_method` VARCHAR(100) NOT NULL DEFAULT '',`paid_date` DATE NULL,`manual_adjustment` DECIMAL(10,2) NOT NULL DEFAULT 0.00,`adjustment_reason` VARCHAR(255) NOT NULL DEFAULT '',`notes` TEXT NULL,`payout_paid` DECIMAL(10,2) NOT NULL DEFAULT 0.00,`payout_method` VARCHAR(100) NOT NULL DEFAULT '',`payout_date` DATE NULL,`payout_source` VARCHAR(150) NOT NULL DEFAULT '',`recipient_url` VARCHAR(500) NOT NULL DEFAULT '',`payoff_notes` TEXT NULL,`updated_by` INT NOT NULL DEFAULT 0,`created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `uniq_fin_team_year` (`raceYear`,`userID`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
 $defs=[
 'mrl_financial_fee_history'=>['raceYear'=>'INT NOT NULL DEFAULT 0','annual_fee'=>'DECIMAL(10,2) NOT NULL DEFAULT 0.00','effective_date'=>'DATE NULL','reason'=>"VARCHAR(255) NOT NULL DEFAULT ''",'changed_by'=>'INT NOT NULL DEFAULT 0','created_at'=>'DATETIME NULL'],
 'mrl_financial_team_year'=>['raceYear'=>'INT NOT NULL DEFAULT 0','userID'=>'INT NOT NULL DEFAULT 0','teamName'=>"VARCHAR(255) NOT NULL DEFAULT ''",'userName'=>"VARCHAR(255) NOT NULL DEFAULT ''",'amount_paid'=>'DECIMAL(10,2) NOT NULL DEFAULT 0.00','paid_method'=>"VARCHAR(100) NOT NULL DEFAULT ''",'paid_date'=>'DATE NULL','manual_adjustment'=>'DECIMAL(10,2) NOT NULL DEFAULT 0.00','adjustment_reason'=>"VARCHAR(255) NOT NULL DEFAULT ''",'notes'=>'TEXT NULL','payout_paid'=>'DECIMAL(10,2) NOT NULL DEFAULT 0.00','payout_method'=>"VARCHAR(100) NOT NULL DEFAULT ''",'payout_date'=>'DATE NULL','payout_source'=>"VARCHAR(150) NOT NULL DEFAULT ''",'recipient_url'=>"VARCHAR(500) NOT NULL DEFAULT ''",'payoff_notes'=>'TEXT NULL','updated_by'=>'INT NOT NULL DEFAULT 0','created_at'=>'DATETIME NULL','updated_at'=>'DATETIME NULL']];
 foreach($defs as $t=>$cols)foreach($cols as $c=>$def)if(!colExists($dbo,$t,$c)){$dbo->exec("ALTER TABLE `".$t."` ADD COLUMN `".$c."` ".$def);$notes[]='added '.$t.'.'.$c;}
 try{$dbo->exec("ALTER TABLE `mrl_financial_team_year` ADD UNIQUE KEY `uniq_fin_team_year` (`raceYear`,`userID`)");$notes[]='added unique key uniq_fin_team_year';}catch(Throwable $e){}
 return $notes;
}
function schemaReport(PDO $dbo):array{$need=['mrl_financial_fee_history'=>['raceYear','annual_fee','effective_date','reason','changed_by','created_at'],'mrl_financial_team_year'=>['raceYear','userID','teamName','userName','amount_paid','paid_method','paid_date','manual_adjustment','adjustment_reason','notes','payout_paid','payout_method','payout_date','payout_source','recipient_url','payoff_notes','updated_by','created_at','updated_at']];$r=[];foreach($need as $t=>$cols){$r[$t]=['exists'=>tableExists($dbo,$t),'missing_columns'=>[]];foreach($cols as $c)if(!colExists($dbo,$t,$c))$r[$t]['missing_columns'][]=$c;}return $r;}
function report(array $checks,string $stage,array $extra=[]):array{return array_merge(['installer'=>'install_admin_paid_payouts_v002','installer_version'=>'v002','report_stage'=>$stage,'report_generated_et'=>nowEt(),'scope'=>['new_or_replaced_files'=>['admin_paid_payouts.php','admin_paid_payouts_helper.php'],'misplaced_files_removed_if_present'=>['race_results/admin_paid_payouts.php','race_results/admin_paid_payouts_helper.php'],'database_tables_preserved_or_upgraded'=>['mrl_financial_fee_history','mrl_financial_team_year'],'does_not_change'=>['Paid_Status_Year.php','race_results/payouts.php','race_results/admin_payouts.php','race_results/payouts_helper.php','existing Financial table','weekly standings/scoring','cron/scheduler','race snapshots']],'result'=>['ok'=>allPass($checks),'checks'=>$checks]],$extra);}
function downloadJson(array $p,string $stage):void{$n='install_admin_paid_payouts_v002_'.$stage.'_'.date('Ymd_His').'.json';header('Content-Type: application/json');header('Content-Disposition: attachment; filename="'.$n.'"');echo json_encode($p,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES);exit;}

$action=$_POST['action']??$_GET['action']??'';$checks=[];$msg='';$cls='info';
$page=base64_decode($PAGE_B64,true);$helper=base64_decode($HELPER_B64,true);
addCheck($checks,'Installer running from /public_html/_installers',realpath($installerDir)===realpath($publicRoot.'/_installers'),true,$installerDir);
addCheck($checks,'Embedded root page decoded',is_string($page),true,is_string($page)?strlen($page).' bytes':'decode failed');
addCheck($checks,'Embedded root helper decoded',is_string($helper),true,is_string($helper)?strlen($helper).' bytes':'decode failed');
addCheck($checks,'Root page SHA-256 verified',is_string($page)&&hash('sha256',$page)===$PAGE_SHA,true,$PAGE_SHA);
addCheck($checks,'Root helper SHA-256 verified',is_string($helper)&&hash('sha256',$helper)===$HELPER_SHA,true,$HELPER_SHA);
addCheck($checks,'Public root writable',is_writable($publicRoot),true,$publicRoot);
foreach(['config.php','config_mrl.php','class.user.php','mrl_team/mrl_theme_helper.php','race_results/payouts_helper.php','race_results/payouts.php'] as $f)addCheck($checks,'Required dependency: '.$f,is_file($publicRoot.'/'.$f),true,$publicRoot.'/'.$f);
$dboOk=isset($dbo)&&$dbo instanceof PDO; if(!$dboOk){@require_once $publicRoot.'/config.php';@require_once $publicRoot.'/config_mrl.php';$dboOk=isset($dbo)&&$dbo instanceof PDO;}
addCheck($checks,'PDO database connection available',$dboOk,true,$dboOk?'PDO ready':'PDO not available');
if(is_string($page)&&is_string($helper)){$tp=tempnam(sys_get_temp_dir(),'mrlapp_p_');$th=tempnam(sys_get_temp_dir(),'mrlapp_h_');file_put_contents($tp,$page);file_put_contents($th,$helper);[$op,$lp]=phpLint($tp);[$oh,$lh]=phpLint($th);addCheck($checks,'php -l candidate: admin_paid_payouts.php',$op,true,$lp);addCheck($checks,'php -l candidate: admin_paid_payouts_helper.php',$oh,true,$lh);@unlink($tp);@unlink($th);}
$schemaBefore=$dboOk?schemaReport($dbo):[];
addCheck($checks,'Existing root page state',true,false,is_file($targetPage)?'Exists and will be backed up/replaced':'Absent — will be NEW');
addCheck($checks,'Existing root helper state',true,false,is_file($targetHelper)?'Exists and will be backed up/replaced':'Absent — will be NEW');
addCheck($checks,'Misplaced race_results page state',true,false,is_file($oldPage)?'Present — will be backed up then removed after validation':'Not present');
addCheck($checks,'Misplaced race_results helper state',true,false,is_file($oldHelper)?'Present — will be backed up then removed after validation':'Not present');
if($action==='download_precheck')downloadJson(report($checks,'PRECHECK',['schema_before'=>$schemaBefore,'candidate_sha256'=>['admin_paid_payouts.php'=>$PAGE_SHA,'admin_paid_payouts_helper.php'=>$HELPER_SHA]]),'PRECHECK');
if($action==='apply'){
 if(!allPass($checks)){$msg='Apply blocked: PRECHECK has a required failure.';$cls='bad';}
 else try{
  if(!is_dir($backupDir)&&!mkdir($backupDir,0755,true))throw new RuntimeException('Could not create backup folder.');
  $state=['applied_at_et'=>nowEt(),'backup_dir'=>$backupDir,'target_page_existed'=>is_file($targetPage),'target_helper_existed'=>is_file($targetHelper),'old_page_existed'=>is_file($oldPage),'old_helper_existed'=>is_file($oldHelper)];
  foreach([[$targetPage,'root_admin_paid_payouts.php'],[$targetHelper,'root_admin_paid_payouts_helper.php'],[$oldPage,'race_results_admin_paid_payouts.php'],[$oldHelper,'race_results_admin_paid_payouts_helper.php']] as $x)if(is_file($x[0])&&!copy($x[0],$backupDir.'/'.$x[1]))throw new RuntimeException('Backup failed for '.$x[0]);
  file_put_contents($stateFile,json_encode($state,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));
  $schemaNotes=ensureSchema($dbo);
  if(!atomicWrite($targetHelper,$helper))throw new RuntimeException('Could not install root helper.');
  if(!atomicWrite($targetPage,$page))throw new RuntimeException('Could not install root page.');
  [$okp,$lop]=phpLint($targetPage);[$okh,$loh]=phpLint($targetHelper);if(!$okp||!$okh)throw new RuntimeException('Installed-file lint failed. Page: '.$lop.' Helper: '.$loh);
  if(hash_file('sha256',$targetPage)!==$PAGE_SHA||hash_file('sha256',$targetHelper)!==$HELPER_SHA)throw new RuntimeException('Installed hash verification failed.');
  if(is_file($oldPage)&&!@unlink($oldPage))throw new RuntimeException('Could not remove misplaced race_results/admin_paid_payouts.php');
  if(is_file($oldHelper)&&!@unlink($oldHelper))throw new RuntimeException('Could not remove misplaced race_results/admin_paid_payouts_helper.php');
  $msg='PASS — fresh root-level Paid + Payouts v002 installed and validated. Financial tables/data preserved.';$cls='good';
 }catch(Throwable $e){$msg='APPLY FAILED: '.$e->getMessage();$cls='bad';}
}
if($action==='rollback'){try{if(!is_file($stateFile))throw new RuntimeException('No installer state file found.');$s=json_decode((string)file_get_contents($stateFile),true);$b=(string)($s['backup_dir']??'');
 if(!empty($s['target_page_existed'])&&is_file($b.'/root_admin_paid_payouts.php'))copy($b.'/root_admin_paid_payouts.php',$targetPage);else @unlink($targetPage);
 if(!empty($s['target_helper_existed'])&&is_file($b.'/root_admin_paid_payouts_helper.php'))copy($b.'/root_admin_paid_payouts_helper.php',$targetHelper);else @unlink($targetHelper);
 if(!empty($s['old_page_existed'])&&is_file($b.'/race_results_admin_paid_payouts.php'))copy($b.'/race_results_admin_paid_payouts.php',$oldPage);
 if(!empty($s['old_helper_existed'])&&is_file($b.'/race_results_admin_paid_payouts_helper.php'))copy($b.'/race_results_admin_paid_payouts_helper.php',$oldHelper);
 $msg='ROLLBACK COMPLETE for files. Financial tables/columns/data were intentionally preserved.';$cls='good';}catch(Throwable $e){$msg='ROLLBACK FAILED: '.$e->getMessage();$cls='bad';}}
$post=[];addCheck($post,'Root admin_paid_payouts.php exists',is_file($targetPage),true,$targetPage);addCheck($post,'Root admin_paid_payouts_helper.php exists',is_file($targetHelper),true,$targetHelper);
if(is_file($targetPage)){[$x,$o]=phpLint($targetPage);addCheck($post,'php -l installed root page',$x,true,$o);addCheck($post,'Installed root page SHA matches',hash_file('sha256',$targetPage)===$PAGE_SHA,true,hash_file('sha256',$targetPage)?:'');}
if(is_file($targetHelper)){[$x,$o]=phpLint($targetHelper);addCheck($post,'php -l installed root helper',$x,true,$o);addCheck($post,'Installed root helper SHA matches',hash_file('sha256',$targetHelper)===$HELPER_SHA,true,hash_file('sha256',$targetHelper)?:'');}
addCheck($post,'Misplaced race_results/admin_paid_payouts.php absent',!is_file($oldPage),true,$oldPage);addCheck($post,'Misplaced race_results/admin_paid_payouts_helper.php absent',!is_file($oldHelper),true,$oldHelper);
$schemaAfter=$dboOk?schemaReport($dbo):[];foreach($schemaAfter as $t=>$sr)addCheck($post,'Database schema ready: '.$t,!empty($sr['exists'])&&empty($sr['missing_columns']),true,empty($sr['missing_columns'])?'ready':'missing: '.implode(', ',$sr['missing_columns']));
if($action==='download_postcheck')downloadJson(report($post,'POSTCHECK',['schema_after'=>$schemaAfter,'installed_sha256'=>['admin_paid_payouts.php'=>is_file($targetPage)?hash_file('sha256',$targetPage):'','admin_paid_payouts_helper.php'=>is_file($targetHelper)?hash_file('sha256',$targetHelper):'']]),'POSTCHECK');
?>
