<?php if($msg!==''):?><div class="c <?php echo ih($cls);?>"><strong><?php echo ih($msg);?></strong></div><?php endif;?>
<div class="c"><h2>PRECHECK</h2><table><tr><th>Status</th><th>Check</th><th>Detail</th></tr><?php foreach($checks as $x):?><tr><td class="<?php echo $x['status']==='PASS'?'pass':'fail';?>"><?php echo ih($x['status']);?></td><td><?php echo ih($x['label']);?></td><td><?php echo ih($x['detail']);?></td></tr><?php endforeach;?></table><form method="post"><button class="btn neutral" name="action" value="download_precheck">Export PRECHECK JSON</button><button class="btn apply" name="action" value="apply" <?php echo allPass($checks)?'':'disabled';?>>Apply v002</button></form></div>
<div class="c"><h2>POSTCHECK</h2><table><tr><th>Status</th><th>Check</th><th>Detail</th></tr><?php foreach($post as $x):?><tr><td class="<?php echo $x['status']==='PASS'?'pass':'fail';?>"><?php echo ih($x['status']);?></td><td><?php echo ih($x['label']);?></td><td><?php echo ih($x['detail']);?></td></tr><?php endforeach;?></table><form method="post"><button class="btn neutral" name="action" value="download_postcheck">Export POSTCHECK JSON</button><button class="btn rollback" name="action" value="rollback">Rollback Files</button></form></div></div></body></html>
